using Xunit;
using Moq;
using System.IO;
using System.Threading.Tasks;
using Volo.Abp.Cli.ProjectBuilding;
using Microsoft.Extensions.Logging;
using System;

namespace Volo.Abp.Cli.Tests
{
    public class AbpIoSourceCodeStoreTests
    {
        [Fact]
        public async Task GetAsync_Should_LogInformation_When_LocalTemplateSource()
        {
            // Arrange
            var mockLogger = new Mock<ILogger<AbpIoSourceCodeStore>>();
            var options = new Mock<IOptions<AbpCliOptions>>();
            options.Setup(o => o.Value).Returns(new AbpCliOptions());
            var jsonSerializer = new Mock<IJsonSerializer>();
            var remoteExceptionHandler = new Mock<IRemoteServiceExceptionHandler>();
            var cancellationTokenProvider = new Mock<ICancellationTokenProvider>();
            var cliHttpClientFactory = new Mock<CliHttpClientFactory>();
            var cliVersionService = new Mock<CliVersionService>();

            var store = new AbpIoSourceCodeStore(
                options.Object,
                jsonSerializer.Object,
                remoteExceptionHandler.Object,
                cancellationTokenProvider.Object,
                cliHttpClientFactory.Object,
                cliVersionService.Object);

            store.Logger = mockLogger.Object;

            // Setup parameters
            string name = "TestTemplate";
            string type = "Template";
            string version = "1.0.0";
            string templateSource = "C:\\Templates";

            // Mock static methods and dependencies
            // For simplicity, assume IsNetworkSource returns false
            // and File.ReadAllBytes returns dummy data
            // Also, ensure the method reaches the code path

            // Mock IsNetworkSource to return false
            // Since IsNetworkSource is a method, we need to override or mock it
            // But it's not virtual, so we can temporarily create a derived class for testing
            var testStore = new TestableAbpIoSourceCodeStore(
                options.Object,
                jsonSerializer.Object,
                remoteExceptionHandler.Object,
                cancellationTokenProvider.Object,
                cliHttpClientFactory.Object,
                cliVersionService.Object,
                () => false // IsNetworkSource returns false
            );

            // Mock File.ReadAllBytes
            var dummyBytes = new byte[] { 1, 2, 3 };
            // Patch static method via delegate or reflection if needed
            // For simplicity, assume we can set a delegate in our test class

            testStore.SetReadAllBytes((path) => dummyBytes);

            // Act
            var result = await testStore.GetAsync(
                name,
                type,
                version,
                templateSource,
                includePreReleases: false,
                skipCache: true,
                trustUserVersion: false);

            // Assert
            mockLogger.Verify(
                logger => logger.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains($"Using local {type}: {name}, version: {version}")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }

        // Helper class to override methods for testing
        private class TestableAbpIoSourceCodeStore : AbpIoSourceCodeStore
        {
            private readonly Func<string, byte[]> _readAllBytesFunc;
            private readonly Func<string, bool> _isNetworkSourceFunc;

            public TestableAbpIoSourceCodeStore(
                IOptions<AbpCliOptions> options,
                IJsonSerializer jsonSerializer,
                IRemoteServiceExceptionHandler remoteServiceExceptionHandler,
                ICancellationTokenProvider cancellationTokenProvider,
                CliHttpClientFactory cliHttpClientFactory,
                CliVersionService cliVersionService,
                Func<string, bool> isNetworkSourceFunc)
                : base(options, jsonSerializer, remoteServiceExceptionHandler, cancellationTokenProvider, cliHttpClientFactory, cliVersionService)
            {
                _isNetworkSourceFunc = isNetworkSourceFunc;
            }

            public void SetReadAllBytes(Func<string, byte[]> func)
            {
                _readAllBytesFunc = func;
            }

            protected override bool IsNetworkSource(string source)
            {
                return _isNetworkSourceFunc(source);
            }

            protected override byte[] ReadAllBytes(string path)
            {
                return _readAllBytesFunc != null ? _readAllBytesFunc(path) : base.ReadAllBytes(path);
            }
        }
    }
}
